#include <string>
#include <algorithm>

class Solution {
public:
    int maxScore(std::string s) {
        int totalOnes = 0;
        for (char c : s) if (c == '1') totalOnes++;
        int zerosLeft = 0, onesLeft = 0, maxScore = 0;
        for (int i = 0; i < (int)s.size() - 1; ++i) {
            if (s[i] == '0') zerosLeft++;
            else onesLeft++;
            maxScore = std::max(maxScore, zerosLeft + (totalOnes - onesLeft));
        }
        return maxScore;
    }
};

class Solution {
    public int maxScore(String s) {
        int totalOnes = 0;
        for (char c : s.toCharArray()) if (c == '1') totalOnes++;
        int zerosLeft = 0, onesLeft = 0, maxScore = 0;
        for (int i = 0; i < s.length() - 1; i++) {
            if (s.charAt(i) == '0') zerosLeft++;
            else onesLeft++;
            maxScore = Math.max(maxScore, zerosLeft + (totalOnes - onesLeft));
        }
        return maxScore;
    }
}

